css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: A4 portrait;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
  background: #fff;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
}

.receipt-page,
.receipt-page * {
  box-sizing: border-box;
}

.receipt-page {
  width: 210mm;
  height: 297mm;
  padding: 8mm 9mm;
  overflow: hidden;
  color: #202020;
  background: #fff;
  font-family: "TH Sarabun Document", "Noto Sans Thai", "TH SarabunPSK", sans-serif;
  font-size: 4.15mm;
  font-weight: 400;
  line-height: 1.05;
  page-break-after: always;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.receipt-page.last-page {
  page-break-after: auto;
}

.receipt-page .th,
.receipt-page .en {
  display: block;
}

.receipt-page .en {
  margin-top: -0.2mm;
  font-size: 2.35mm;
  line-height: 2.5mm;
}

.receipt-page .nowrap {
  white-space: nowrap;
}

.receipt-page .truncate {
  overflow: hidden;
  text-overflow: clip;
  white-space: nowrap;
}

.document-header {
  position: relative;
  height: 38mm;
}

.company-logo {
  position: absolute;
  left: 0;
  top: 7.5mm;
  width: 23mm;
  height: 10mm;
  object-fit: contain;
}

.company-block {
  position: absolute;
  left: 25mm;
  top: 2mm;
  width: 105mm;
}

.company-name {
  font-size: 6.1mm;
  line-height: 7.2mm;
  white-space: nowrap;
}

.company-address,
.company-contact {
  font-size: 4.15mm;
  line-height: 5.2mm;
  white-space: nowrap;
}

.company-tax-row {
  position: absolute;
  left: 25mm;
  top: 29.2mm;
  display: flex;
  align-items: baseline;
  gap: 4mm;
  font-size: 3.7mm;
  white-space: nowrap;
}

.document-title {
  position: absolute;
  right: 0;
  top: 17.5mm;
  min-width: 77mm;
  padding: 1.2mm 4.5mm 1.1mm;
  border-radius: 6mm;
  background: #e2a2f5;
  font-size: 6.25mm;
  font-weight: 700;
  line-height: 7mm;
  text-align: center;
  white-space: nowrap;
}

.copy-title {
  position: absolute;
  right: 3mm;
  bottom: 0.8mm;
  width: 72mm;
  font-size: 4.9mm;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
}

.info-section {
  display: grid;
  grid-template-columns: 56% 44%;
  height: 44mm;
  overflow: hidden;
  border: 0.25mm solid #1f1f1f;
  border-radius: 2.8mm;
}

.customer-box,
.invoice-box {
  position: relative;
  padding: 2.2mm 3mm;
}

.customer-box {
  border-right: 0.25mm solid #1f1f1f;
}

.info-row {
  display: flex;
  align-items: flex-start;
  min-height: 5.2mm;
}

.info-label {
  flex: 0 0 auto;
  width: 19mm;
}

.info-label .th,
.info-label .en {
  white-space: nowrap;
}

.info-label.compact {
  width: 15mm;
}

.info-value {
  min-width: 0;
  flex: 1 1 auto;
  padding-top: 0.3mm;
  font-size: 4.05mm;
}

.customer-name {
  margin: 0.3mm 0 0.4mm;
  font-weight: 700;
}

.customer-address {
  height: 10.5mm;
  overflow: hidden;
  font-size: 4.05mm;
  font-weight: 700;
  line-height: 5mm;
}

.customer-meta-grid {
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  column-gap: 2.5mm;
  margin-top: 0.2mm;
}

.customer-meta-grid .info-row {
  min-height: 5.2mm;
}

.customer-meta-grid .info-label {
  font-size: 3.2mm;
}

.customer-meta-grid .info-row:nth-child(3) .info-label {
  width: 26mm;
  font-size: 3mm;
}

.customer-meta-grid .info-row:nth-child(3) .en {
  font-size: 1.9mm;
}

.branch-mark {
  display: inline-block;
  width: 3mm;
  height: 3mm;
  margin-right: 0.7mm;
  border: 0.2mm solid #222;
  text-align: center;
  line-height: 2.6mm;
  vertical-align: 0.3mm;
}

.invoice-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 3mm;
  row-gap: 0.1mm;
}

.invoice-grid .full {
  grid-column: 1 / -1;
}

.invoice-grid .info-label {
  width: 16.5mm;
  font-size: 3.45mm;
}

.invoice-box .info-value {
  font-size: 3.55mm;
}

.invoice-grid .info-label.small {
  width: 14mm;
}

.document-body {
  height: 147mm;
  margin-top: 2mm;
  overflow: hidden;
  border: 0.25mm solid #1f1f1f;
  border-radius: 2.8mm;
}

.items-table {
  width: 100%;
  height: 89mm;
  border-collapse: collapse;
  table-layout: fixed;
}

.items-table col.col-no { width: 8%; }
.items-table col.col-description { width: 47%; }
.items-table col.col-quantity { width: 13%; }
.items-table col.col-unit-price { width: 12%; }
.items-table col.col-discount { width: 9%; }
.items-table col.col-amount { width: 11%; }

.items-table th,
.items-table td {
  border-right: 0.25mm solid #1f1f1f;
}

.items-table th:last-child,
.items-table td:last-child {
  border-right: 0;
}

.items-table thead th {
  height: 10.5mm;
  padding: 1mm 0.8mm 0.4mm;
  border-bottom: 0.25mm solid #1f1f1f;
  font-weight: 400;
  text-align: center;
  vertical-align: top;
}

.items-table tbody tr {
  height: 9.8mm;
}

.items-table tbody td {
  padding: 1.2mm 1mm 0.8mm;
  overflow: hidden;
  font-size: 3.45mm;
  line-height: 4.6mm;
  white-space: nowrap;
  vertical-align: top;
}

.items-table .num {
  text-align: right;
}

.items-table .center {
  text-align: center;
}

.items-table .description {
  font-size: 3.2mm;
  text-align: left;
}

.summary-section {
  display: grid;
  grid-template-columns: 62% 25% 13%;
  height: 58mm;
  border-top: 0.25mm solid #1f1f1f;
}

.summary-left,
.summary-labels,
.summary-values {
  position: relative;
  min-width: 0;
}

.summary-left,
.summary-labels {
  border-right: 0.25mm solid #1f1f1f;
}

.receipt-condition {
  height: 29.5mm;
  padding: 2mm 3mm;
  overflow: hidden;
  font-size: 3.05mm;
  line-height: 4.25mm;
}

.eoe {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 11mm;
  font-size: 2.7mm;
  text-align: center;
}

.amount-in-words {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 9.7mm;
  padding: 2.4mm 2mm 0;
  border-top: 0.25mm solid #1f1f1f;
  background: #f1f1f1;
  font-size: 4mm;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
}

.summary-row {
  position: relative;
  height: 11.7mm;
  padding: 0.9mm 1.2mm 0.2mm;
}

.summary-row .th {
  font-size: 3.65mm;
  line-height: 3.6mm;
}

.summary-row .en {
  font-size: 2.2mm;
  line-height: 2.4mm;
}

.vat-rate {
  position: absolute;
  right: 1.1mm;
  top: 1.6mm;
  font-size: 3.2mm;
  white-space: nowrap;
}

.summary-row.total-label,
.summary-value.total-value {
  height: 11.2mm;
  border-top: 0.25mm solid #1f1f1f;
  background: #f1f1f1;
  font-weight: 700;
}

.summary-value {
  height: 11.7mm;
  padding: 2.2mm 1.2mm 0 0.5mm;
  font-size: 3.75mm;
  text-align: right;
  white-space: nowrap;
}

.summary-value.total-value {
  padding-top: 2.4mm;
  font-size: 5.1mm;
}

.approval-section {
  display: grid;
  grid-template-columns: 34% 37% 29%;
  height: 46mm;
  margin-top: 2mm;
  overflow: hidden;
  border: 0.25mm solid #1f1f1f;
  border-radius: 2.8mm;
}

.approval-column {
  position: relative;
  min-width: 0;
  padding: 2mm 2.5mm;
}

.approval-column:not(:last-child) {
  border-right: 0.25mm solid #1f1f1f;
}

.received-heading {
  font-size: 4.05mm;
  font-weight: 700;
  text-align: center;
}

.signature-row {
  position: absolute;
  left: 2.5mm;
  right: 2.5mm;
  height: 10mm;
}

.signature-row.received {
  top: 19mm;
}

.signature-row.delivery {
  top: 37mm;
}

.signature-line {
  position: absolute;
  left: 0;
  top: 0;
  width: 66%;
  border-bottom: 0.2mm solid #555;
}

.date-line {
  position: absolute;
  right: 0;
  top: 0;
  width: 28%;
  border-bottom: 0.2mm solid #555;
  text-align: center;
}

.signature-caption,
.date-caption {
  position: absolute;
  top: 2mm;
  font-size: 2.75mm;
  white-space: nowrap;
}

.signature-caption { left: 0; }
.date-caption { right: 0; }

.notes-list {
  margin: 0;
  padding: 0 0 0 4.5mm;
  font-size: 3.15mm;
  line-height: 4.9mm;
}

.notes-list li {
  padding-left: 0.5mm;
}

.on-behalf {
  font-size: 3mm;
}

.signature-company {
  margin-top: 0.5mm;
  font-size: 2.9mm;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
}

.authorized-line,
.approved-line {
  position: absolute;
  left: 4mm;
  right: 4mm;
  border-bottom: 0.2mm solid #555;
}

.authorized-line { top: 20mm; }
.approved-line { top: 38.5mm; }

.authorized-caption,
.approved-caption {
  position: absolute;
  left: 1mm;
  right: 1mm;
  font-size: 3.15mm;
  text-align: center;
  white-space: nowrap;
}

.authorized-caption { top: 22mm; }
.approved-caption { top: 40.3mm; }

.print-meta {
  position: absolute;
  left: 3mm;
  right: 3mm;
  top: 31.8mm;
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  gap: 1.5mm;
  font-size: 2.8mm;
}

.print-meta span:nth-child(2),
.print-meta span:nth-child(3) {
  text-align: right;
}

@media screen {
  body {
    background: #d8d8d8;
  }

  .receipt-page {
    margin: 8mm auto;
    box-shadow: 0 0 3mm rgba(0, 0, 0, 0.25);
  }
}

/* Compact controls for the two information panels. */
.info-label {
  white-space: nowrap;
}

.customer-meta-grid .info-row:nth-child(3) .info-label {
  width: 29mm;
  font-size: 2.65mm;
}

.customer-meta-grid .info-row:nth-child(3) .info-value {
  font-size: 3.2mm;
}

.invoice-box {
  padding: 1.4mm 2.5mm;
}

.invoice-grid {
  column-gap: 2mm;
  row-gap: 0;
}

.invoice-box .info-row {
  min-height: 6.5mm;
}

.invoice-grid .info-label,
.invoice-grid .info-label.small {
  width: 18mm;
  font-size: 3.15mm;
}

.invoice-grid .info-label .th {
  font-size: 3.15mm;
  line-height: 3.1mm;
}

.invoice-grid .info-label .en {
  margin-top: 0;
  font-size: 1.65mm;
  line-height: 1.7mm;
}

.invoice-box .info-value {
  padding-top: 0.45mm;
  font-size: 3.2mm;
  white-space: nowrap;
}
